SELECT customers.city, DATE_FORMAT(customers.signup_date, 'yyyy-MM') AS signup_month, ROUND((100 * SUM(CASE WHEN web_events.page = '/product' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_product, COUNT(CASE WHEN web_events.event_type = 'purchase' THEN 1 END) AS purchase_count FROM web_events INNER JOIN sessions ON web_events.session_id = sessions.id LEFT JOIN customers ON sessions.customer_id = customers.id GROUP BY customers.city, DATE_FORMAT(customers.signup_date, 'yyyy-MM') ORDER BY 3 DESC;
